"use client";

import { useState } from "react";
import Link from "next/link";
import { List, X } from "@phosphor-icons/react";
import { brand, nav } from "@/lib/content/dossier";

export function SiteNav() {
  const [open, setOpen] = useState(false);

  return (
    <header className="sticky top-0 z-50 border-b border-border bg-bg/80 backdrop-blur-md">
      <nav
        aria-label="Primary"
        className="mx-auto flex h-16 max-w-6xl items-center justify-between gap-6 px-5"
      >
        <Link
          href="/"
          className="flex items-baseline gap-2 font-semibold tracking-tight"
        >
          <span className="text-fg">{brand.name}</span>
          <span className="hidden text-sm font-normal text-muted sm:inline">
            {brand.tagline}
          </span>
        </Link>

        {/* Desktop links */}
        <div className="hidden items-center gap-8 md:flex">
          <ul className="flex items-center gap-6 text-sm text-muted">
            {nav.links.map((l) => (
              <li key={l.href}>
                <Link href={l.href} className="transition-colors hover:text-fg">
                  {l.label}
                </Link>
              </li>
            ))}
          </ul>
          <Link
            href={nav.cta.href}
            className="rounded-full bg-accent px-4 py-2 text-sm font-medium text-accent-fg transition-transform active:translate-y-px"
          >
            {nav.cta.label}
          </Link>
        </div>

        {/* Mobile toggle */}
        <button
          type="button"
          className="md:hidden"
          aria-expanded={open}
          aria-controls="mobile-menu"
          aria-label={open ? "Close menu" : "Open menu"}
          onClick={() => setOpen((v) => !v)}
        >
          {open ? <X size={24} weight="bold" /> : <List size={24} weight="bold" />}
        </button>
      </nav>

      {/* Mobile menu */}
      {open ? (
        <div
          id="mobile-menu"
          className="border-t border-border bg-bg px-5 py-4 md:hidden"
        >
          <ul className="flex flex-col gap-1 text-base">
            {nav.links.map((l) => (
              <li key={l.href}>
                <Link
                  href={l.href}
                  className="block py-2 text-fg"
                  onClick={() => setOpen(false)}
                >
                  {l.label}
                </Link>
              </li>
            ))}
          </ul>
          <Link
            href={nav.cta.href}
            className="mt-3 inline-block rounded-full bg-accent px-4 py-2 text-sm font-medium text-accent-fg"
            onClick={() => setOpen(false)}
          >
            {nav.cta.label}
          </Link>
        </div>
      ) : null}
    </header>
  );
}

