"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { WaveSine, Vibrate, SpeakerHigh } from "@phosphor-icons/react";
import {
  scenarios,
  type BodyZone,
  type BuzzScenario,
} from "@/lib/haptics/buzz-language";

/**
 * The signature interactive moment: feel the buzz-language.
 *
 * Three channels carry the same signal so nobody is left out:
 *   - vibration  (navigator.vibrate, follows the real ms pattern)
 *   - audio      (a short tone proxy, for sighted and Deaf-blind users)
 *   - text       (an aria-live description, the full experience without sight)
 *
 * The on-screen body does ONE gentle pulse per trigger. It never strobes at the
 * vibration frequency (WCAG 2.3.1 seizure safety), and collapses to a static
 * highlight under prefers-reduced-motion.
 */
export function HapticDemo() {
  const reduce = useReducedMotion();
  const [active, setActive] = useState<BuzzScenario | null>(null);
  const [trigger, setTrigger] = useState(0);
  const [announce, setAnnounce] = useState("");
  const audioRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    return () => {
      audioRef.current?.close().catch(() => {});
    };
  }, []);

  const playTone = useCallback(
    (tone: BuzzScenario["tone"]) => {
      if (reduce) return; // audio is motion-adjacent; honour the quiet preference
      try {
        const Ctor =
          window.AudioContext ||
          (window as unknown as { webkitAudioContext: typeof AudioContext })
            .webkitAudioContext;
        audioRef.current ??= new Ctor();
        const ctx = audioRef.current;
        if (ctx.state === "suspended") void ctx.resume();
        const pulse = 0.11;
        const gap = 0.07;
        for (let i = 0; i < tone.pulses; i++) {
          const t0 = ctx.currentTime + i * (pulse + gap);
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();
          osc.type = "sine";
          osc.frequency.value = tone.frequency;
          gain.gain.setValueAtTime(0, t0);
          gain.gain.linearRampToValueAtTime(0.14, t0 + 0.012);
          gain.gain.linearRampToValueAtTime(0.0001, t0 + pulse);
          osc.connect(gain).connect(ctx.destination);
          osc.start(t0);
          osc.stop(t0 + pulse + 0.02);
        }
      } catch {
        /* audio unavailable; text + vibration still carry the signal */
      }
    },
    [reduce],
  );

  const run = useCallback(
    (s: BuzzScenario) => {
      setActive(s);
      setTrigger((t) => t + 1);
      setAnnounce(s.description);
      if (typeof navigator !== "undefined" && "vibrate" in navigator) {
        navigator.vibrate?.(s.pattern);
      }
      playTone(s.tone);
    },
    [playTone],
  );

  const isActive = (zone: BodyZone) => active?.zones.includes(zone) ?? false;

  return (
    <div className="rounded-2xl border border-border bg-surface p-5 sm:p-6">
      <div className="flex items-center justify-between gap-3">
        <p className="flex items-center gap-2 text-sm font-medium text-fg">
          <WaveSine size={18} weight="bold" className="text-accent" />
          Feel the buzz-language
        </p>
        <span className="text-xs text-muted">A simulation</span>
      </div>

      <div className="mt-5 grid gap-6 sm:grid-cols-[minmax(0,1fr)_9rem] sm:items-center">
        {/* Scenario controls */}
        <div className="order-2 flex flex-col gap-2 sm:order-1">
          <p id="haptic-help" className="mb-1 text-sm text-muted">
            Choose a moment on the road. Feel it, hear it, read it.
          </p>
          {scenarios.map((s) => {
            const on = active?.id === s.id;
            return (
              <button
                key={s.id}
                type="button"
                onClick={() => run(s)}
                aria-describedby="haptic-help"
                aria-pressed={on}
                className={`flex items-center justify-between gap-3 rounded-xl border px-4 py-3 text-left text-sm font-medium transition-colors ${
                  on
                    ? "border-accent bg-accent/10 text-fg"
                    : "border-border text-fg hover:border-accent/60 hover:bg-surface-2"
                }`}
              >
                <span>{s.label}</span>
                <span className="flex items-center gap-1.5 text-muted">
                  <Vibrate size={15} weight={on ? "fill" : "regular"} />
                  <SpeakerHigh size={15} weight={on ? "fill" : "regular"} />
                </span>
              </button>
            );
          })}
        </div>

        {/* Body map */}
        <div className="order-1 flex justify-center sm:order-2">
          <BodyMap active={active} isActive={isActive} trigger={trigger} reduce={!!reduce} />
        </div>
      </div>

      {/* The signal as text, announced to assistive tech */}
      <p
        aria-live="polite"
        className="mt-5 min-h-[2.75rem] rounded-xl bg-surface-2 px-4 py-3 text-sm text-fg"
      >
        {announce || "Nothing is buzzing yet. Choose a moment above to feel it."}
      </p>

      <p className="mt-3 text-xs text-muted">
        Vibration plays on supported devices, mostly phones. Everyone gets the
        tone and the words. On the real wearable, this reaches the whole body at
        once.
      </p>
    </div>
  );
}

function BodyMap({
  isActive,
  trigger,
  reduce,
}: {
  active: BuzzScenario | null;
  isActive: (zone: BodyZone) => boolean;
  trigger: number;
  reduce: boolean;
}) {
  // One gentle pulse per trigger. Never a strobe.
  const pulse = reduce
    ? { opacity: 0.85 }
    : { opacity: [0.5, 1, 0.85], scale: [1, 1.05, 1] };

  const zone = (on: boolean) =>
    on
      ? { fill: "var(--accent)", stroke: "var(--accent)" }
      : { fill: "var(--surface-2)", stroke: "var(--border)" };

  const common = {
    strokeWidth: 2,
    style: { transformBox: "fill-box", transformOrigin: "center" } as const,
  };

  return (
    <svg
      viewBox="0 0 140 220"
      role="img"
